import itertools, sys
from collections import Counter
sys.path.insert(0, "src")
from accountability.authorization import intersection_pattern, _split_glob

frags = ["", "a", "b", "c"]
patterns = sorted({
    "*".join(parts)
    for nstars in range(1, 3)
    for parts in itertools.product(frags, repeat=nstars + 1)
})
def middles_of(p):
    pre, mid, suf = _split_glob(p)
    return tuple(x for x in mid if x)

for p1 in patterns:
    for p2 in patterns:
        g = intersection_pattern(p1, p2)
        if g is None:
            continue
        c1, c2 = Counter(middles_of(p1)), Counter(middles_of(p2))
        cg = Counter(middles_of(g))
        for frag in c1.keys() | c2.keys():
            # repeats preserved: merged run keeps max of the two counts
            assert cg[frag] == max(c1[frag], c2[frag]), (p1, p2, g, frag)
print("occurrence preservation OK", len(patterns), "patterns")
